```sql
alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create or replace function public.is_friend(target_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.friendships f
    where (f.requester_id = auth.uid() and f.addressee_id = target_user_id)
       or (f.requester_id = target_user_id and f.addressee_id = auth.uid())
    and f.status = 'accepted'
  );
$$;

create policy "posts_select_authenticated"
on public.posts for select to authenticated
using (
  author_id = auth.uid()
  or audience = 'public'
  or public.is_friend(author_id)
);

create policy "posts_insert_own"
on public.posts for insert to authenticated
with check (author_id = auth.uid());

create policy "posts_update_own"
on public.posts for update to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy "posts_delete_own"
on public.posts for delete to authenticated
using (author_id = auth.uid());

create policy "friendships_select_participant"
on public.friendships for select to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy "friendships_insert_requester"
on public.friendships for insert to authenticated
with check (requester_id = auth.uid() and status = 'pending');

create policy "friendships_update_addressee_accept"
on public.friendships for update to authenticated
using (addressee_id = auth.uid() and status = 'pending')
with check (addressee_id = auth.uid() and status = 'accepted');

create policy "friendships_delete_participant"
on public.friendships for delete to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

revoke all on public.friendships from anon;
revoke all on public.posts from anon;
revoke all on public.friendships from authenticated;
revoke all on public.posts from authenticated;

grant select on public.posts to anon;
grant select on public.posts to authenticated;
grant select, insert, update, delete on public.posts to authenticated;
grant select, insert, update, delete on public.friendships to authenticated;
grant execute on function public.is_friend(uuid) to authenticated;
```

