create or replace function public.friendship_columns_guard()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'pending' then
      raise exception 'new friendship requests must be pending';
    end if;
    if new.requester_id = new.addressee_id then
      raise exception 'cannot send a friend request to yourself';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.requester_id <> old.requester_id or new.addressee_id <> old.addressee_id then
      raise exception 'friendship endpoints cannot be changed';
    end if;
    if old.status = 'accepted' then
      raise exception 'accepted friendships cannot be changed';
    end if;
    if auth.uid() <> old.addressee_id then
      raise exception 'only the addressee of a pending request can accept it';
    end if;
    if new.status <> 'accepted' then
      raise exception 'pending requests cannot be updated';
    end if;
    return new;
  end if;

  return new;
end;
$$;

create trigger friendships_columns_guard
  before insert or update on public.friendships
  for each row execute function public.friendship_columns_guard();

