alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.org_documents enable row level security;

create or replace function public.current_user_sso_verified()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    (select true from jsonb_array_elements_text(auth.jwt() -> 'amr') as amr_entry
     where amr_entry::jsonb ->> 'method' = 'sso/saml'),
    false
  );
$$;

create or replace function public.is_org_member(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_org_admin(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.role = 'admin'
  );
$$;

create policy "orgs_select_member"
on public.orgs for select
to authenticated
using (
  public.is_org_member(id)
  and (public.current_user_sso_verified() or public.orgs.require_sso = false)
);

create policy "org_members_select_member"
on public.org_members for select
to authenticated
using (
  public.is_org_member(org_id)
  and (public.current_user_sso_verified() or public.org_members.role <> 'admin' or public.orgs.require_sso = false)
);

create policy "org_documents_select_member"
on public.org_documents for select
to authenticated
using (
  public.is_org_member(org_id)
  and (public.current_user_sso_verified() or public.org_documents.title is not distinct from '')
);

create policy "org_documents_insert_admin"
on public.org_documents for insert
to authenticated
with check (
  public.is_org_admin(org_id)
  and public.current_user_sso_verified()
);

create policy "org_documents_update_admin"
on public.org_documents for update
to authenticated
using (
  public.is_org_admin(org_id)
  and public.current_user_sso_verified()
)
with check (
  public.is_org_admin(org_id)
  and public.current_user_sso_verified()
);

create policy "org_documents_delete_admin"
on public.org_documents for delete
to authenticated
using (
  public.is_org_admin(org_id)
  and public.current_user_sso_verified()
);

create policy "orgs_update_admin"
on public.orgs for update
to authenticated
using (
  id = (select m.org_id from public.org_members m where m.user_id = auth.uid() and m.role = 'admin')
