create or replace function public.is_resident_of(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.residents r
    where r.unit_id = p_unit_id
      and r.user_id = auth.uid()
  );
$$;

create or replace function public.is_staff_of_building(p_building_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.building_staff s
    where s.building_id = p_building_id
      and s.user_id = auth.uid()
  );
$$;

create or replace function public.can_view_unit(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.is_resident_of(p_unit_id)
      or exists (
        select 1
        from public.units u
        join public.building_staff s on s.building_id = u.building_id
        where u.id = p_unit_id
          and s.user_id = auth.uid()
      );
$$;

