create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_current_highest_bid numeric(10, 2);
  v_min_increment numeric(10, 2);
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'auction not found';
  end if;

  if v_auction.ends_at < now() then
    raise exception 'auction has ended';
  end if;

  if v_auction.seller_id = v_uid then
    raise exception 'cannot bid on own auction';
  end if;

  if v_auction.highest_bid is null then
    v_current_highest_bid := v_auction.starting_price;
  else
    v_current_highest_bid := v_auction.highest_bid;
  end if;

  if p_amount < v_current_highest_bid then
    raise exception 'bid amount is too low';
  end if;

  if v_current_highest_bid is not null then
    if p_amount < v_current_highest_bid + v_auction.min_increment then
      raise exception 'bid amount is too low';
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_uid, p_amount);

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_uid
  where id = p_auction_id;

  return p_amount;
end;
$$;

