create or replace function public.enforce_class_spots_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.class_id is distinct from old.class_id
     or new.user_id is distinct from old.user_id then
    raise exception 'class_id and user_id cannot be changed';
  end if;

  if old.status = 'enrolled' then
    raise exception 'cannot update an enrolled spot';
  end if;

  if new.status = 'enrolled' then
    if not public.class_has_capacity(old.class_id, (select capacity from public.classes where id = old.class_id)) then
      raise exception 'no capacity for enrolled status';
    end if;
    if not (old.status = 'waitlisted' and new.status = 'enrolled') then
      raise exception 'can only move a waitlisted spot to enrolled';
    end if;
  else
    if new.status <> 'waitlisted' then
      raise exception 'invalid status';
    end if;
  end if;

  return new;
end;
$$;

